/**
 * Who may open a grant's content (summary, requirements, source PDF): read access, not edit.
 * A developer or platform admin sees every grant; anyone else sees federal grants and their own
 * state's. Untagged rows count as federal so legacy grants stay viewable; a missing row is denied.
 */

import { DynamoDBClient, GetItemCommand } from "@aws-sdk/client-dynamodb";
import { marshall, unmarshall } from "@aws-sdk/util-dynamodb";
import { getSupportedStateCodes, LEGACY_STATELESS_ADMIN_IS_PLATFORM } from "./index.mjs";

/** Like parseRoles, but a bare non-JSON claim is taken as one role. */
function viewerRoles(raw) {
  if (Array.isArray(raw)) return raw.filter((r) => typeof r === "string");
  if (typeof raw !== "string" || raw.trim() === "") return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((r) => typeof r === "string") : [];
  } catch {
    return [raw];
  }
}

export function grantViewerScope(event) {
  const claims = event?.requestContext?.authorizer?.jwt?.claims || {};
  const roles = viewerRoles(claims["custom:role"]);
  const stateRaw = String(claims["custom:state"] || "").trim().toUpperCase();
  const state = getSupportedStateCodes().has(stateRaw) ? stateRaw : "";

  if (roles.includes("Developer")) return { role: "developer", state };
  if (roles.includes("PlatformAdmin")) return { role: "regularAdmin", state: "" };
  if (roles.includes("Admin")) {
    if (state) return { role: "stateAdmin", state };
    return LEGACY_STATELESS_ADMIN_IS_PLATFORM
      ? { role: "regularAdmin", state: "" }
      : { role: "unscopedAdmin", state: "" };
  }
  return { role: "user", state };
}

/** `{ scope, state, status }` from the grant's metadata row, or null when there is no row or it can't be read. */
export async function readGrantRow(tableName, nofoName) {
  if (!tableName || !nofoName) return null;
  try {
    const result = await new DynamoDBClient().send(
      new GetItemCommand({ TableName: tableName, Key: marshall({ nofo_name: nofoName }) })
    );
    if (!result.Item) return null;
    const row = unmarshall(result.Item);
    return {
      scope: typeof row.scope === "string" ? row.scope : null,
      state: typeof row.state === "string" ? row.state : null,
      status: typeof row.status === "string" ? row.status : null,
    };
  } catch (err) {
    console.warn(`Could not read scope/state for ${nofoName}:`, err.message);
    return null;
  }
}

export const effectiveGrantScope = (row) => (row ? row.scope || "federal" : null);

export function canViewGrant(callerScope, row) {
  if (callerScope.role === "developer" || callerScope.role === "regularAdmin") return true;
  const scope = effectiveGrantScope(row);
  if (scope === "federal") return true;
  return scope === "state" && Boolean(row.state) && row.state === callerScope.state;
}
